// Re-generates the PAPER table inside packages/compositions/compositions/shader-bg/shader-bg.html. Scout agent, 2026-10-24.
//
//   bun third_party/paper-shaders/extract.ts <paper-design/shaders checkout> <paper commit> <Remocn checkout> <remocn commit>
//
// Reads (as TEXT — no upstream code is imported or run):
//   paper:  packages/shaders/src/shaders/<type>.ts         fragment shader template + *Meta + enum maps   (Apache-2.0)
//           packages/shaders/src/{shader-utils,vertex-shader,shader-sizing,get-shader-noise-texture}.ts
//           packages/shaders-react/src/shaders/<type>.tsx   defaultPreset params                           (Apache-2.0)
//   remocn: registry/remocn/shader-<type>-<look>/index.tsx  named look presets + their one-line comment     (MIT)
// and writes one JSON table between the @paper-shaders markers. Fails on any template expression it cannot resolve.
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";

const TYPES = ["mesh-gradient", "grain-gradient", "warp", "swirl"] as const;
const ENUMS: Record<string, string> = { "grain-gradient": "GrainGradientShapes", warp: "WarpPatterns" };
const BEGIN = "/* @paper-shaders:begin (generated by third_party/paper-shaders/extract.ts; do not edit by hand) */";
const END = "/* @paper-shaders:end */";

const read = (p: string) => readFileSync(p, "utf8").replace(/\r\n/g, "\n");

/** `export const NAME = \`...\`` string constants (GLSL snippets) from a TS file. */
function snippets(text: string, into: Record<string, string>) {
  const re = /export const (\w+)\s*(?::\s*string)?\s*=\s*`([\s\S]*?)`;/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) into[m[1]] = m[2];
}

/** `export const NAME = { a: 1, b: 2 } (as const);` with numeric values only. */
function numberMaps(text: string, into: Record<string, Record<string, number>>) {
  const re = /export const (\w+)(?::[^=]+)?\s*=\s*\{([^{}]*)\}\s*(?:as const)?;/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) {
    const obj: Record<string, number> = {};
    for (const kv of m[2].matchAll(/(\w+)\s*:\s*(-?[\d.]+)/g)) obj[kv[1]] = Number(kv[2]);
    if (Object.keys(obj).length) into[m[1]] = obj;
  }
}

/** A plain TS object literal (strings, numbers, booleans, arrays) → JSON value; `...name` spreads come from `spreads`. */
function literal(body: string, spreads: Record<string, Record<string, unknown>> = {}): Record<string, unknown> {
  let extra: Record<string, unknown> = {};
  let text = body.replace(/\/\/[^\n]*/g, "");
  text = text.replace(/\.\.\.(\w+)\s*,?/g, (_, name: string) => {
    if (!spreads[name]) throw new Error(`unknown spread ${name}`);
    extra = { ...extra, ...spreads[name] };
    return "";
  });
  text = text
    .replace(/'([^']*)'/g, (_, s: string) => JSON.stringify(s))
    .replace(/([{,]\s*)([A-Za-z_]\w*)\s*:/g, '$1"$2":')
    .replace(/,(\s*[}\]])/g, "$1");
  return { ...extra, ...JSON.parse(text) };
}

/** Text of the first balanced `{ … }` starting at or after `from`. */
function braces(text: string, from: number): string {
  const a = text.indexOf("{", from);
  let depth = 0;
  for (let i = a; i < text.length; i++) {
    if (text[i] === "{") depth++;
    else if (text[i] === "}" && --depth === 0) return text.slice(a, i + 1);
  }
  throw new Error("unbalanced braces");
}

function resolveTemplate(tpl: string, snips: Record<string, string>, maps: Record<string, Record<string, number>>): string {
  return tpl.replace(/\$\{\s*([^}]+?)\s*\}/g, (_, expr: string) => {
    if (snips[expr] !== undefined) return snips[expr];
    const m = expr.match(/^(\w+)\.(\w+)(?:\s*\+\s*(\d+))?$/);
    if (m && maps[m[1]]?.[m[2]] !== undefined) return String(maps[m[1]][m[2]] + Number(m[3] ?? 0));
    throw new Error(`cannot resolve template expression \${${expr}}`);
  });
}

function main() {
  const [paperDir, paperCommit, remocnDir, remocnCommit] = process.argv.slice(2);
  if (!remocnCommit) throw new Error("usage: bun third_party/paper-shaders/extract.ts <paper checkout> <paper commit> <Remocn checkout> <remocn commit>");
  const src = join(paperDir, "packages/shaders/src");
  const snips: Record<string, string> = {};
  const maps: Record<string, Record<string, number>> = {};
  for (const f of ["shader-utils.ts", "vertex-shader.ts", "shader-sizing.ts"]) snippets(read(join(src, f)), snips);
  numberMaps(read(join(src, "shader-sizing.ts")), maps);
  const noise = read(join(src, "get-shader-noise-texture.ts")).match(/const noiseSrc\s*=\s*'([^']+)'/)?.[1];
  if (!noise?.startsWith("data:image/png;base64,")) throw new Error("noise texture not found");

  const sizingText = read(join(src, "shader-sizing.ts"));
  const spreads: Record<string, Record<string, unknown>> = {};
  for (const name of ["defaultObjectSizing", "defaultPatternSizing"]) {
    const at = sizingText.indexOf(`export const ${name}`);
    spreads[name] = literal(braces(sizingText, sizingText.indexOf("=", at)));
  }

  const shaders: Record<string, unknown> = {};
  for (const type of TYPES) {
    const text = read(join(src, "shaders", `${type}.ts`));
    numberMaps(text, maps);
    const frag = text.match(/export const \w+FragmentShader\s*:\s*string\s*=\s*`([\s\S]*?)`;/)?.[1];
    if (!frag) throw new Error(`${type}: fragment shader not found`);
    const react = read(join(paperDir, "packages/shaders-react/src/shaders", `${type}.tsx`));
    const at = react.indexOf("export const defaultPreset");
    const preset = literal(braces(react, react.indexOf("params:", at)), spreads);
    shaders[type] = {
      glsl: resolveTemplate(frag, snips, maps),
      defaults: preset,
      enum: ENUMS[type] ? maps[ENUMS[type]] : null,
      noise: /u_noiseTexture/.test(frag),
    };
  }

  const looks: Record<string, unknown> = {};
  const reg = join(remocnDir, "registry/remocn");
  for (const type of TYPES) {
    const short = type.replace("-gradient", "");
    looks[short] = { type, params: {}, about: `Paper's default ${type}`, source: `paper-design/shaders packages/shaders-react/src/shaders/${type}.tsx defaultPreset` };
    for (const dir of readdirSync(reg).filter((d) => d.startsWith(`shader-${type}-`)).sort()) {
      const file = join(reg, dir, "index.tsx");
      if (!existsSync(file)) continue;
      const text = read(file);
      const at = text.search(/export const \w+Preset\s*=/);
      if (at < 0) continue;
      const params = literal(braces(text, at));
      const about = text.match(/^\/\/ ([^\n]+)$/m)?.[1] ?? "";
      looks[`${short}-${dir.slice(`shader-${type}-`.length)}`] = { type, params, about, source: `Remocn registry/remocn/${dir}/index.tsx` };
    }
  }

  const table = {
    paper: { repo: "https://github.com/paper-design/shaders", commit: paperCommit, licence: "Apache-2.0" },
    remocn: { repo: "https://github.com/Remocn/remocn", commit: remocnCommit, licence: "MIT" },
    vertex: resolveTemplate(snips.vertexShaderSource, snips, maps),
    fit: maps.ShaderFitOptions,
    noise,
    shaders,
    looks,
  };
  const html = resolve(import.meta.dir, "../../packages/compositions/compositions/shader-bg/shader-bg.html");
  const text = read(html);
  const a = text.indexOf(BEGIN);
  const b = text.indexOf(END);
  if (a < 0 || b < a) throw new Error("markers not found in shader-bg.html");
  writeFileSync(html, `${text.slice(0, a)}${BEGIN}\nvar PAPER = ${JSON.stringify(table)};\n${END}${text.slice(b + END.length)}`);
  console.log(`wrote ${TYPES.length} shaders, ${Object.keys(looks).length} looks into ${html}`);
  console.log(`looks: ${Object.keys(looks).join(" ")}`);
}

main();
